def f(x):
    return x - 1 / x - 3

def bisect(a, b):
    for _ in range(200):
        m = (a + b) / 2
        if f(a) * f(m) <= 0:
            b = m
        else:
            a = m
    return (a + b) / 2

vals = set()
for a, b in [(-2.0, -0.001), (0.001, 5.0)]:
    x = bisect(a, b)
    vals.add(round(x * x + 1 / (x * x)))
print(vals.pop())

