from fractions import Fraction
N = 24
best = Fraction(0)
for i in range(1, 6 * N):
    for j in range(1, 6 * N - i):
        a = Fraction(i, N)
        b = Fraction(j, N)
        c = 6 - a - b
        if c > 0:
            v = a * a * b * c
            if v > best:
                best = v
print(best)

def g(x):
    y = (7 - x) / (1 + x)
    return x * x + y * y - 10

vals = set()
N = 200000
xs = [-60 + 120 * i / N for i in range(N + 1)]
for a, b in zip(xs, xs[1:]):
    if a == -1 or b == -1:
        continue
    ga, gb = g(a), g(b)
    if ga * gb < 0 and abs(ga) < 1000 and abs(gb) < 1000:
        lo, hi = a, b
        for _ in range(100):
            m = (lo + hi) / 2
            if g(lo) * g(m) <= 0:
                hi = m
            else:
                lo = m
        x = (lo + hi) / 2
        y = (7 - x) / (1 + x)
        vals.add(round(x * x * y + x * y * y))
print(vals.pop())
